<template><div class="blog-home"><section class="blog-hero"><div><span class="hero-kicker">PERSONAL KNOWLEDGE GARDEN</span><h1>把复杂的技术，<br><em>写成清晰的答案。</em></h1><p>这里记录工程实践、架构思考与持续成长。不是信息的搬运，而是问题解决之后留下的路径。</p><div class="hero-search"><input v-model="keyword" placeholder="搜索文章、技术或问题…" @keyup.enter="load"/><button @click="load">搜索</button></div></div><div class="hero-card"><span>最新发布</span><template v-if="featured"><h2>{{featured.title}}</h2><p>{{featured.summary||'一篇值得慢慢读完的文章。'}}</p><router-link :to="`/blog/posts/${featured.slug}`">开始阅读 →</router-link></template><el-empty v-else description="文章正在生长中"/></div></section>
  <section class="archive"><aside><div class="aside-block"><b>分类</b><button :class="{active:!category}" @click="category='';load()">全部文章</button><button v-for="item in archive.categories" :key="item" :class="{active:category===item}" @click="category=item;load()">{{item}}</button></div><div class="aside-block tags"><b>热门标签</b><div><button v-for="item in archive.tags" :key="item" :class="{active:tag===item}" @click="tag=tag===item?'':item;load()"># {{item}}</button></div></div></aside>
    <div class="article-column"><div class="section-head"><div><small>ARCHIVE</small><h2>所有文章</h2></div><span>{{archive.posts.length}} 篇公开文章</span></div><div class="article-grid"><router-link v-for="post in archive.posts" :key="post.id" class="article-card" :to="`/blog/posts/${post.slug}`"><div v-if="post.coverUrl" class="article-cover" :style="{backgroundImage:`url(${post.coverUrl})`}"/><div class="article-card-body"><div class="article-meta"><span>{{post.category||'随笔'}}</span><time>{{date(post.publishedAt)}}</time></div><h3>{{post.title}}</h3><p>{{post.summary||'打开文章阅读全文。'}}</p><div class="article-bottom"><div><span v-for="item in tags(post.tags).slice(0,3)" :key="item">#{{item}}</span></div><small>{{post.viewCount}} 阅读</small></div></div></router-link></div><el-empty v-if="!loading&&!archive.posts.length" description="没有找到匹配的文章"/></div>
  </section></div>
</template>
<script setup lang="ts">import{onMounted,reactive,ref,computed}from'vue';import{listPublicBlog,type BlogArchive}from'@/api/blog';const archive=reactive<BlogArchive>({posts:[],categories:[],tags:[]}),keyword=ref(''),category=ref(''),tag=ref(''),loading=ref(false);const featured=computed(()=>archive.posts[0]);async function load(){loading.value=true;try{Object.assign(archive,(await listPublicBlog({keyword:keyword.value||undefined,category:category.value||undefined,tag:tag.value||undefined})).data);}finally{loading.value=false;}}const date=(v:string)=>new Date(v).toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric'});const tags=(v:string|null)=>v?v.split(',').filter(Boolean):[];onMounted(load);</script>
