{padding:9px 12px;color:#718096;text-align:left;cursor:pointer;background:transparent;border:0;border-radius:9px}.aside-block button:hover,.aside-block button.active{color:#0f766e;background:#e7f5f2;font-weight:750}.tags>div{display:flex;flex-wrap:wrap;gap:6px}.tags button{padding:7px 9px;font-size:12px}.section-head{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:24px}.section-head h2{margin:7px 0 0;font-family:Georgia,"Songti SC",serif;font-size:34px}.section-head>span{color:#94a3b8;font-size:13px}.article-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.article-card{overflow:hidden;color:inherit;text-decoration:none;background:rgb(255 255 255 / 76%);border:1px solid #e4e9ee;border-radius:20px;box-shadow:0 12px 36px rgb(15 23 42 / 5%);transition:.2s ease}.article-card:hover{border-color:#a7d9d0;box-shadow:0 22px 55px rgb(15 118 110 / 12%);transform:translateY(-4px)}.article-cover{height:180px;background-position:center;background-size:cover}.article-card-body{padding:22px}.article-meta,.article-bottom{display:flex;align-items:center;justify-content:space-between;gap:10px}.article-meta{color:#8996a8;font-size:12px}.article-meta span{color:#0f766e;font-weight:750}.article-card h3{margin:14px 0 10px;color:#1d293d;font-family:Georgia,"Songti SC",serif;font-size:22px;line-height:1.45}.article-card p{display:-webkit-box;min-height:52px;margin:0;overflow:hidden;color:#718096;line-height:1.7;-webkit-box-orient:vertical;-webkit-line-clamp:2}.article-bottom{margin-top:18px;padding-top:14px;border-top:1px solid #edf1f5;color:#94a3b8;font-size:11px}.article-bottom div{display:flex;gap:8px}.article-bottom div span{color:#64748b}@media(max-width:850px){.blog-home{padding:20px 18px 0}.blog-hero{grid-template-columns:1fr;gap:24px;min-height:auto;padding:50px 0}.blog-hero h1{font-size:42px}.archive{grid-template-columns:1fr;gap:15px}.archive aside{display:flex;gap:30px;overflow:auto}.aside-block{min-width:150px}.article-grid{grid-template-columns:1fr}}@media(max-width:480px){.blog-hero h1{font-size:36px}.section-head h2{font-size:28px}.section-head>span{display:none}.hero-card{padding:24px}}</style>
